+        </div>
+    </div>
+}
+else if (errorMessage is not null)
+{
+    <div class="alert alert-danger" role="alert">
+        <strong>Error:</strong> @errorMessage
+    </div>
+}
+else
+{
+    <!-- Stats bar -->
+    <div class="row g-2 mb-3">
+        <div class="col">
+            <div class="stats-card bg-light rounded p-2 text-center">
+                <div class="fw-bold fs-4">@allTasks.Count</div>
+                <small class="text-muted">Total Tasks</small>
+            </div>
+        </div>
+        @foreach (var col in columns)
+        {
+            <div class="col">
+                <div class="stats-card bg-light rounded p-2 text-center">
+                    <div class="fw-bold fs-4">@GetTasksForColumn(col).Count</div>
+                    <small class="text-muted">@col</small>
+                </div>
+            </div>
+        }
+        <div class="col">
+            <div class="stats-card bg-light rounded p-2 text-center">
+                <div class="fw-bold fs-4 text-danger">@allTasks.Count(t => t.DueDate < DateTime.Today)</div>
+                <small class="text-muted">Overdue</small>
+            </div>
+        </div>
+    </div>
+
+    <!-- Search bar -->
+    <div class="mb-3">
+        <input type="text"
+               class="form-control"
+               placeholder="Search tasks by title…"
+               @bind="searchText"
+               @bind:event="oninput" />
+    </div>
+
+    <!-- Kanban columns -->
+    <div class="row g-3">
+        @for (int i = 0; i < columns.Length; i++)
+        {
+            var colIndex = i;
+            var colName = columns[colIndex];
+            var tasks = GetFilteredTasksForColumn(colName);
+
+            <div class="col-md-4">
+                <div class="kanban-column rounded p-3">
+                    <div class="d-flex justify-content-between align-items-center mb-3">
+                        <h5 class="mb-0">@colName</h5>
+                        <span class="badge bg-secondary">@tasks.Count</span>
+                    </div>
+
+                    @foreach (var task in tasks)
+                    {
+                        <div class="card mb-2 task-card">
+                            <div class="card-body p-2">
+                                <div class="fw-semibold mb-1">@task.Title</div>
+                                <div class="d-flex justify-content-between align-items-center mb-1">
+                                    <small class="text-muted">@task.Assignee</small>
+                                    <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
+                                </div>
+                                <div class="d-flex justify-content-between align-items-center">
+                                    <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
+                                    <div>
+                                        @if (colIndex > 0)
+                                        {
+                                            <button class="btn btn-outline-secondary btn-sm me-1"
+                                                    @onclick="() => MoveTask(task.Id, columns[colIndex - 1])"
+                                                    disabled="@isSaving">
+                                                ← Move Left
+                                            </button>
+                                        }
+                                        @if (colIndex < columns.Length - 1)
+                                        {
+                                            <button class="btn btn-outline-secondary btn-sm"
+                                                    @onclick="() => MoveTask(task.Id, columns[colIndex + 1])"
+                                                    disabled="@isSaving">
+                                                Move Right →
+                                            </button>
+                                        }
+                                    </div>
+                                </div>
+                            </div>
+                        </div>
+                    }
+
+                    @if (addingToColumn == colName)
+                    {
+                        <div class="card mb-2 border-primary">
+                            <div class="card-body p-2">
+                                <input type="text" class="form-control form-control-sm mb-2"
+                                       placeholder="Title" @bind="newTitle" />
+                                <input type="text" class="form-control form-control-sm mb-2"
+                                       placeholder="Assignee" @bind="newAssignee" />
+                                <select class="form-select form-select-sm mb-2" @bind="newPriority">
+                                    <option value="High">High</option>
+                                    <option value="Medium">Medium</option>
+                                    <option value="Low">Low</option>
+                                </select>
+                                <input type="date" class="form-control form-control-sm mb-2"
+                                       @bind="newDueDate" />
+                                <div class="d-flex gap-2">
+                                    <button class="btn btn-primary btn-sm flex-fill"
+                                            @onclick="() => SaveNewTask(colName)"
+                                            disabled="@isSaving">
+                                        Save
+                                    </button>
+                                    <button class="btn btn-outline-secondary btn-sm flex-fill"
+                                            @onclick="CancelAdd"
+                                            disabled="@isSaving">
+                                        Cancel
+                                    </button>
+                                </div>
+                            </div>
+                        </div>
+                    }
+
+                    <button class="btn btn-outline-primary btn-sm w-100"
+                            @onclick="() => StartAdd(colName)"
+                            disabled="@(addingToColumn is not null)">
+                        + Add Task
+                    </button>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private static readonly string[] columns = ["To Do", "In Progress", "Done"];
+
+    private List<TaskItem> allTasks = new();
+    private bool isLoading = true;
+    private bool isSaving;
+    private string? errorMessage;
+    private string searchText = string.Empty;
+
+    // Add-task form state
+    private string? addingToColumn;
+    private string newTitle = string.Empty;
+    private string newAssignee = string.Empty;
+    private string newPriority = "Medium";
+    private DateTime newDueDate = DateTime.Today.AddDays(7);
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private List<TaskItem> GetTasksForColumn(string status) =>
+        allTasks.Where(t => t.Status == status).ToList();
+
+    private List<TaskItem> GetFilteredTasksForColumn(string status) =>
+        allTasks
+            .Where(t => t.Status == status &&
+                        (string.IsNullOrWhiteSpace(searchText) ||
+                         t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)))
+            .ToList();
+
+    private static string GetPriorityClass(string priority) => priority switch
+    {
+        "High"   => "bg-danger",
+        "Medium" => "bg-warning text-dark",
+        "Low"    => "bg-success",
+        _        => "bg-secondary"
+    };
+
+    private async Task MoveTask(int taskId, string newStatus)
+    {
+        isSaving = true;
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var idx = allTasks.FindIndex(t => t.Id == taskId);
+            if (idx >= 0)
+            {
+                allTasks[idx] = allTasks[idx] with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isSaving = false;
+        }
+    }
+
+    private void StartAdd(string column)
+    {
+        addingToColumn = column;
+        newTitle = string.Empty;
+        newAssignee = string.Empty;
+        newPriority = "Medium";
+        newDueDate = DateTime.Today.AddDays(7);
+    }
+
+    private void CancelAdd() => addingToColumn = null;
+
+    private async Task SaveNewTask(string column)
+    {
+        if (string.IsNullOrWhiteSpace(newTitle))
+            return;
+
+        isSaving = true;
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(newTitle.Trim(), newAssignee.Trim(), newPriority, newDueDate);
+
+            // If created in a column other than "To Do", move it
+            if (column != "To Do")
+            {
+                await TaskService.UpdateTaskStatusAsync(created.Id, column);
+                created = created with { Status = column };
+            }
+
+            allTasks.Add(created);
+            addingToColumn = null;
+        }
+        catch (Exception ex)
+        {
+            errorMessage = ex.Message;
+        }
+        finally
+        {
+            isSaving = false;
+        }
+    }
+}
+

